    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address logAddr, uint val1, uint val2) public payable {
        require(logAddr != address(0));
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;
        uint minSumAfterLogFile = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetMinSum(val1); if (__ESBMC_reverted()) return;
        uint minSumAfterFirstSet = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetMinSum(val2); if (__ESBMC_reverted()) return;
        uint minSumAfterSecondSet = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(minSumAfterLogFile == 0 && minSumAfterFirstSet == val1 && minSumAfterSecondSet == val2);
    }
